def parse_records(text):
    lines = text.splitlines()
    out = []
    for l in lines:
        if l.strip().startswith('#'):
            continue  # drop full-line comments only
        if '#' in l:
            l = l.split('#', 1)[0]  # strip inline comment, keep content
        out.append(l.strip())
    return out  # preserve empty lines

